    const hooks: OrchestratorHooks = {
      ...throwingBeforeSession(failure),
      onError: async (hookSession, error) => {
        seen = {session: hookSession, error};
      },
    };
    const orchestrator = createChatOrchestrator(providerThatCounts({count: 0}), promptBuilder, undefined, {hooks});

    const outcome = await outcomeOf(orchestrator.processMessage(session));

    expect({
      outcome,
      sameSession: seen.session === session,
      sameError: seen.error === failure,
    }).toEqual({outcome: 'before session failed', sameSession: true, sameError: true});
  });

  it('runs afterSession after onError with the session exactly as beforeSession was handed it', async () => {
    const failure = new Error('before session failed');
    const calls = {count: 0};
    const session = createSession('hello');
    const callOrder: string[] = [];
    let cleanupSession: ChatSession | undefined;
    const hooks: OrchestratorHooks = {
      ...throwingBeforeSession(failure),
      onError: async () => {
        callOrder.push('onError');
      },
      afterSession: async (hookSession) => {
        callOrder.push('afterSession');
        cleanupSession = hookSession;
      },
    };
    const orchestrator = createChatOrchestrator(providerThatCounts(calls), promptBuilder, undefined, {hooks});

    const outcome = await outcomeOf(orchestrator.processMessage(session));

    expect({
      outcome,
      callOrder,
      sameSession: cleanupSession === session,
      entries: cleanupSession?.entries,
      providerCalls: calls.count,
    }).toEqual({
      outcome: 'before session failed',
      callOrder: ['onError', 'afterSession'],
      sameSession: true,
      entries: [{role: 'user', content: 'hello', timestamp: SENT_AT}],
      providerCalls: 0,
